#!/usr/bin/env python3
"""The check for audit-event/t2. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))

    ok, out = ws.py('import datetime as d\nfrom decimal import Decimal\nfrom tally import payments\nfrom tally._generated.records import Payment\np = Payment("P-1", "INV-2024-0017", Decimal("100.00"), "EUR", d.date(2024, 3, 20))\nfrom tally import audit\naudit.clear()\nr = payments.refund(p, "20.00", d.date(2024, 3, 25))\nassert (r.payment_reference, str(r.amount), r.currency, r.refunded_on) == ("P-1", "20.00", "EUR", d.date(2024, 3, 25)), r\nimport json\nprint(json.dumps(audit.events(), default=str))')
    ws.check("the task's own assertions", ok, out)
    events = json.loads(out.strip().splitlines()[-1]) if ok else []
    ws.signals["followed"] = bool(events)
    recorded = [e for e in events if re.fullmatch(r"[a-z_]+(\.[a-z_]+)+", str(e.get("event", ""))) and 'INV-2024-0017' in json.dumps(e, default=str)]
    ws.check("rule: the change was recorded with tally.audit.record('<noun>.<verb>', invoice=...)", bool(recorded), f"audit events: {events}")


if __name__ == "__main__":
    main(check)
